text:
& .account-hub-thundermail-divider {
  color: var(--color-text-secondary);
  text-align: center;
  font-size: 0.923rem;
  font-weight: 400;
  line-height: 100%;

  &::before,
  &::after {
    content: "";
    background: var(--color-surface-border);
    inline-size: 38px;
    block-size: 1px;
    display: inline-block;
    vertical-align: middle;
  }
}
